// Normalize input from internal request or Telegram callback
const input = $input.item.json;

// Telegram callback (Payment Done / Cancel)
if (input.callback_query) {
  const callbackData = input.callback_query.data || '';
  const parts = callbackData.split('_');
  // Format: payment_confirm_BOOKINGID or payment_cancel_BOOKINGID

  return {
    source: 'telegram_callback',
    event_type: parts[1] === 'confirm' ? 'payment_confirmed' : 'payment_cancelled',
    booking_id: parts[2],
    confirmed_by: input.callback_query.from?.username || input.callback_query.from?.first_name,
    callback_message_id: input.callback_query.message?.message_id,
    callback_chat_id: input.callback_query.message?.chat?.id
  };
}

// Internal create booking request from WF2
return {
  source: 'internal',
  event_type: 'create_booking',
  property_id: input.property_id,
  booking_id: input.booking_id || `BK${Date.now()}`,
  guest_name: input.guest_name,
  guest_email: input.guest_email,
  guest_phone: input.guest_phone,
  check_in_date: input.check_in_date,
  check_out_date: input.check_out_date,
  num_guests: input.num_guests,
  amount: input.total_amount,
  currency: input.currency || 'USD',
  owner_chat_id: input.owner_chat_id
};

// Prepare owner notification with Payment Done button
const booking = $('Normalize Event').item.json;
const property = $input.item.json;

const message = `🏠 *New Booking - Awaiting Payment*

📋 *Booking ID:* ${booking.booking_id}
🏡 *Property:* ${property.property_name || booking.property_id}

👤 *Guest:* ${booking.guest_name}
📧 *Email:* ${booking.guest_email}
📱 *Phone:* ${booking.guest_phone || 'Not provided'}

📅 *Check-in:* ${booking.check_in_date}
📅 *Check-out:* ${booking.check_out_date}
👥 *Guests:* ${booking.num_guests}

💰 *Total Amount:* $${booking.amount} ${booking.currency}

⏳ *Status:* Awaiting Payment Confirmation

Once you receive payment, click the button below to confirm the booking.`;

const inlineKeyboard = [
  [
    { text: '✅ Payment Done', callback_data: `payment_confirm_${booking.booking_id}` },
    { text: '❌ Cancel', callback_data: `payment_cancel_${booking.booking_id}` }
  ]
];

return {
  chat_id: property.owner_chat_id || booking.owner_chat_id,
  message: message,
  inline_keyboard: inlineKeyboard,
  booking_id: booking.booking_id,
  parse_mode: 'Markdown'
};

// Return booking data to calling workflow
const booking = $('Normalize Event').item.json;

return {
  success: true,
  booking_id: booking.booking_id,
  status: 'pending_payment',
  message: `Booking ${booking.booking_id} created. Owner notified for payment confirmation.`
};

