// Prepare calendar URLs for fetching
const property = $input.item.json;
const calendars = [];

if (property.airbnb_calendar_url) {
  calendars.push({
    platform: 'airbnb',
    url: property.airbnb_calendar_url,
    property_id: property.property_id
  });
}
if (property.vrbo_calendar_url) {
  calendars.push({
    platform: 'vrbo',
    url: property.vrbo_calendar_url,
    property_id: property.property_id
  });
}
if (property.booking_com_calendar_url) {
  calendars.push({
    platform: 'booking_com',
    url: property.booking_com_calendar_url,
    property_id: property.property_id
  });
}

return calendars.map(c => ({ json: c }));

// Parse iCal data and extract events
const input = $input.item.json;
const icalData = typeof input === 'string' ? input : input.data || '';
const property_id = $('Prepare Calendar URLs').item.json.property_id;
const platform = $('Prepare Calendar URLs').item.json.platform;

const events = [];

// Simple iCal parser
const lines = icalData.split(/\r?\n/);
let currentEvent = null;

for (const line of lines) {
  if (line.startsWith('BEGIN:VEVENT')) {
    currentEvent = {};
  } else if (line.startsWith('END:VEVENT') && currentEvent) {
    if (currentEvent.dtstart && currentEvent.dtend) {
      events.push({
        property_id: property_id,
        platform: platform,
        external_id: currentEvent.uid || `${platform}_${Date.now()}`,
        summary: currentEvent.summary || 'Blocked',
        check_in: currentEvent.dtstart,
        check_out: currentEvent.dtend,
        description: currentEvent.description || ''
      });
    }
    currentEvent = null;
  } else if (currentEvent) {
    const [key, ...valueParts] = line.split(':');
    const value = valueParts.join(':');

    if (key.startsWith('DTSTART')) {
      currentEvent.dtstart = value.replace(/T.*/, '');
    } else if (key.startsWith('DTEND')) {
      currentEvent.dtend = value.replace(/T.*/, '');
    } else if (key === 'UID') {
      currentEvent.uid = value;
    } else if (key === 'SUMMARY') {
      currentEvent.summary = value;
    } else if (key === 'DESCRIPTION') {
      currentEvent.description = value;
    }
  }
}

return {
  property_id: property_id,
  platform: platform,
  events_count: events.length,
  events: events,
  synced_at: new Date().toISOString()
};

// Upsert external bookings into database
const allItems = $input.all();
const upserts = [];

for (const item of allItems) {
  const data = item.json;
  for (const event of (data.events || [])) {
    upserts.push({
      property_id: event.property_id,
      external_platform: event.platform,
      external_booking_id: event.external_id,
      guest_name: event.summary,
      check_in_date: event.check_in,
      check_out_date: event.check_out,
      booking_status: 'confirmed',
      booking_type: 'external',
      notes: event.description,
      synced_at: new Date().toISOString()
    });
  }
}

return { upserts: upserts, total: upserts.length };

// Generate iCal export for our bookings
const items = $input.all();

let ical = 'BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//PropertyManager//EN\n';

for (const item of items) {
  const b = item.json;
  if (b.booking_id && b.check_in_date && b.check_out_date) {
    const startDate = b.check_in_date.replace(/-/g, '');
    const endDate = b.check_out_date.replace(/-/g, '');

    ical += 'BEGIN:VEVENT\n';
    ical += `UID:${b.booking_id}@propertymanager\n`;
    ical += `DTSTART;VALUE=DATE:${startDate}\n`;
    ical += `DTEND;VALUE=DATE:${endDate}\n`;
    ical += `SUMMARY:${b.guest_name || 'Booked'}\n`;
    ical += `DESCRIPTION:Booking ID: ${b.booking_id}\n`;
    ical += 'END:VEVENT\n';
  }
}

ical += 'END:VCALENDAR';

return { ical_content: ical, events_exported: items.length };

