// Normalize input from any channel into standard format
const input = $input.item.json;
let normalized = {
  channel: 'unknown',
  sender_id: null,
  sender_name: null,
  message_text: '',
  is_callback: false,
  callback_data: null,
  customer_id: null
};

// Telegram message
if (input.message?.text) {
  normalized.channel = 'telegram';
  normalized.sender_id = String(input.message.chat.id);
  normalized.sender_name = input.message.from?.first_name || 'Guest';
  normalized.message_text = input.message.text;
}
// Telegram callback
else if (input.callback_query) {
  normalized.channel = 'telegram';
  normalized.sender_id = String(input.callback_query.message.chat.id);
  normalized.sender_name = input.callback_query.from?.first_name || 'Guest';
  normalized.is_callback = true;
  normalized.callback_data = input.callback_query.data;
  normalized.message_text = input.callback_query.data;
}
// WhatsApp
else if (input.entry?.[0]?.changes?.[0]?.value?.messages?.[0]) {
  const msg = input.entry[0].changes[0].value.messages[0];
  const contact = input.entry[0].changes[0].value.contacts?.[0];
  normalized.channel = 'whatsapp';
  normalized.sender_id = msg.from;
  normalized.sender_name = contact?.profile?.name || 'Guest';
  normalized.message_text = msg.text?.body || msg.interactive?.button_reply?.title || '';
  normalized.is_callback = !!msg.interactive;
  normalized.callback_data = msg.interactive?.button_reply?.id || null;
}
// Twilio SMS
else if (input.Body && input.From) {
  normalized.channel = 'sms';
  normalized.sender_id = input.From;
  normalized.sender_name = 'Guest';
  normalized.message_text = input.Body;
}

normalized.timestamp = new Date().toISOString();
return normalized;

// Merge customer_id with normalized data
const normalized = $('Normalize Input').item.json;
const customerResult = $input.item.json;

// Use customer_id from DB or fallback to a default for new guests
const customerId = customerResult?.customer_id || '00000000-0000-0000-0000-000000000001';

return {
  ...normalized,
  customer_id: customerId
};

// Calculate AI cost after agent execution
const normalized = $('Merge Customer ID').item.json;
const aiOutput = $input.item.json;

// GPT-4o-mini pricing (Jan 2026): $0.15/1M input, $0.60/1M output
const INPUT_COST_PER_1K = 0.00015;
const OUTPUT_COST_PER_1K = 0.0006;

// Estimate tokens (approximately 4 chars per token)
const systemPromptTokens = 800;
const messageTokens = Math.ceil((normalized.message_text || '').length / 4);
const inputTokens = systemPromptTokens + messageTokens + 200; // 200 for context

// Output is the AI response
const outputText = aiOutput.output || '';
const outputTokens = Math.ceil(outputText.length / 4);

// Calculate cost
const inputCost = (inputTokens / 1000) * INPUT_COST_PER_1K;
const outputCost = (outputTokens / 1000) * OUTPUT_COST_PER_1K;
const totalCost = inputCost + outputCost;

return {
  ...aiOutput,
  customer_id: normalized.customer_id,
  sender_id: normalized.sender_id,
  channel: normalized.channel,
  cost_calculation: {
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cost_usd: totalCost
  }
};

// Prepare budget alert notification
const data = $input.item.json;
const alertType = data.alert_threshold;
const remaining = data.budget_remaining || 0;
const isPaused = data.is_paused || false;

let alertEmoji, alertTitle, alertMessage;

if (alertType === '50_percent') {
  alertEmoji = '⚠️';
  alertTitle = 'API Budget: 50% Used';
  alertMessage = `You have used 50% of your monthly API budget. Remaining: $${remaining.toFixed(2)}`;
} else if (alertType === '80_percent') {
  alertEmoji = '🔶';
  alertTitle = 'API Budget: 80% Used';
  alertMessage = `You have used 80% of your monthly API budget. Remaining: $${remaining.toFixed(2)}. Consider reducing usage.`;
} else if (alertType === '100_percent') {
  alertEmoji = '🔴';
  alertTitle = 'API Budget Exhausted';
  alertMessage = `Your monthly API budget is exhausted. AI features will use template responses until next month.`;
}

return {
  alert_type: alertType,
  alert_emoji: alertEmoji,
  alert_title: alertTitle,
  alert_message: alertMessage,
  customer_id: $('Merge Customer ID').item.json.customer_id,
  original_output: data
};

