// Merge incoming data with loaded context
const input = $('When Called by Other Workflow').item.json;
const context = $input.item.json;

let conversationHistory = [];
try {
  conversationHistory = context.conversation_history ? JSON.parse(context.conversation_history) : [];
} catch (e) {
  conversationHistory = [];
}

let collectedData = {};
try {
  collectedData = context.collected_data ? JSON.parse(context.collected_data) : {};
} catch (e) {
  collectedData = {};
}

// Extract dates from message using regex patterns
const message = input.message_text || '';
const datePattern = /(\d{4}-\d{2}-\d{2})/g;
const foundDates = message.match(datePattern) || [];

// Try to extract check-in/check-out from collected data or message
let checkIn = collectedData.check_in || (foundDates[0] || null);
let checkOut = collectedData.check_out || (foundDates[1] || null);

return {
  // Session info
  conversation_id: context.conversation_id || `conv_${Date.now()}`,
  contact_id: input.sender_id,
  channel: input.channel,

  // Current message
  user_message: input.message_text,
  is_callback: input.is_callback || false,
  callback_data: input.callback_data || null,

  // Conversation state
  stage: context.conversation_stage || 'greeting',
  history: conversationHistory,
  collected: collectedData,

  // Property info (if associated)
  property_id: context.property_id || input.property_id || null,
  property_name: context.property_name || null,
  property_type: context.property_type || null,
  base_price: context.base_price || null,
  max_guests: context.max_guests || null,
  amenities: context.amenities || null,
  house_rules: context.house_rules || null,
  check_in_time: context.check_in_time || '15:00',
  check_out_time: context.check_out_time || '11:00',
  owner_name: context.owner_name || null,
  owner_contact: context.owner_contact || null,
  preferred_platform: context.preferred_platform || 'telegram',

  // Dates for competing offer check
  detected_check_in: checkIn,
  detected_check_out: checkOut,

  // AI context
  ai_category: input.category || 'BOOKING_INQUIRY',
  ai_confidence: input.confidence || 0.8,
  suggested_response: input.suggested_response || null
};

// Detect if there are competing offers and prepare data
const context = $('Prepare Context').item.json;
const competingOffers = $input.all().map(i => i.json).filter(d => d.deal_id);

// Check if we have valid dates to compare
const hasValidDates = context.detected_check_in && context.detected_check_out;

// If no dates yet or no competing offers, continue normal flow
if (!hasValidDates || competingOffers.length === 0) {
  return [{
    json: {
      ...context,
      has_competing_offers: false,
      competing_offers: [],
      competing_count: 0,
      flow_type: 'normal'
    }
  }];
}

// Calculate priority score for current inquiry
const calculatePriorityScore = (offer) => {
  let score = 0;

  const checkIn = new Date(offer.check_in_date || offer.detected_check_in);
  const checkOut = new Date(offer.check_out_date || offer.detected_check_out);
  const nights = Math.ceil((checkOut - checkIn) / (1000 * 60 * 60 * 24));
  const totalValue = parseFloat(offer.total_amount) || (nights * (context.base_price || 150));
  const dailyRate = nights > 0 ? totalValue / nights : 0;

  // Lead time (days until check-in)
  const now = new Date();
  const leadTime = Math.ceil((checkIn - now) / (1000 * 60 * 60 * 24));

  // Pricing factors
  score += dailyRate / 10;
  score += totalValue / 100;

  // Length of stay bonuses
  if (nights >= 7) score += 10;
  if (nights >= 14) score += 20;
  if (nights >= 28) score += 30;

  // Lead time factors
  if (leadTime < 3) score -= 15;
  if (leadTime >= 7) score += 3;
  if (leadTime >= 14) score += 5;
  if (leadTime >= 30) score += 8;

  // Time-based factor (first come advantage)
  const createdAt = new Date(offer.created_at || new Date());
  const hoursAgo = (now - createdAt) / (1000 * 60 * 60);
  if (hoursAgo < 1) score += 5; // Recent inquiry bonus
  if (hoursAgo > 24) score -= 5; // Older inquiry penalty

  return Math.round(score * 10) / 10;
};

// Score all competing offers
const scoredCompetitors = competingOffers.map(offer => ({
  ...offer,
  priority_score: offer.priority_score || calculatePriorityScore(offer),
  nights: Math.ceil((new Date(offer.check_out_date) - new Date(offer.check_in_date)) / (1000 * 60 * 60 * 24))
}));

// Calculate current inquiry's score
const currentInquiryScore = calculatePriorityScore({
  check_in_date: context.detected_check_in,
  check_out_date: context.detected_check_out,
  total_amount: null,
  created_at: new Date().toISOString()
});

const currentNights = Math.ceil(
  (new Date(context.detected_check_out) - new Date(context.detected_check_in)) / (1000 * 60 * 60 * 24)
);

return [{
  json: {
    ...context,
    has_competing_offers: true,
    competing_offers: scoredCompetitors,
    competing_count: scoredCompetitors.length,
    current_inquiry_score: currentInquiryScore,
    current_inquiry_nights: currentNights,
    current_inquiry_estimated_total: currentNights * (context.base_price || 150),
    flow_type: 'conflicting_offer'
  }
}];

// Format owner notification for competing offers
const data = $json;
const competitors = data.competing_offers;

// Create new deal for current inquiry
const newDealId = `DEAL-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

// Build all offers array (competitors + current)
const allOffers = [
  ...competitors.map((c, i) => ({
    offer_number: i + 1,
    deal_id: c.deal_id,
    guest_name: c.guest_name || 'Guest',
    guest_phone: c.guest_phone,
    check_in: c.check_in_date,
    check_out: c.check_out_date,
    nights: c.nights,
    total_amount: c.total_amount || (c.nights * (data.base_price || 150)),
    priority_score: c.priority_score,
    channel: c.channel || 'unknown',
    created_at: c.created_at,
    is_current: false
  })),
  {
    offer_number: competitors.length + 1,
    deal_id: newDealId,
    guest_name: data.collected.guest_name || 'New Guest',
    guest_phone: data.contact_id,
    check_in: data.detected_check_in,
    check_out: data.detected_check_out,
    nights: data.current_inquiry_nights,
    total_amount: data.current_inquiry_estimated_total,
    priority_score: data.current_inquiry_score,
    channel: data.channel,
    created_at: new Date().toISOString(),
    is_current: true
  }
];

// Sort by priority score (highest first)
allOffers.sort((a, b) => b.priority_score - a.priority_score);

// Re-number after sorting
allOffers.forEach((offer, i) => {
  offer.offer_number = i + 1;
  offer.is_recommended = i === 0;
});

// Build notification message
let message = `🔔 *CONFLICTING OFFERS DETECTED*\n`;
message += `━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;
message += `🏠 *Property:* ${data.property_name}\n`;
message += `📅 *Dates:* ${data.detected_check_in} → ${data.detected_check_out}\n`;
message += `👥 *${allOffers.length} guests* want the same dates!\n\n`;

allOffers.forEach((offer, i) => {
  message += `━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  message += `*OFFER ${offer.offer_number}*`;

  if (offer.is_recommended) {
    message += ` ⭐ RECOMMENDED`;
  }
  if (offer.is_current) {
    message += ` 🆕 NEW`;
  }

  message += `\n\n`;
  message += `👤 Guest: ${offer.guest_name}\n`;
  message += `📱 Contact: ${offer.guest_phone}\n`;
  message += `📅 ${offer.check_in} → ${offer.check_out}\n`;
  message += `🌙 ${offer.nights} nights\n`;
  message += `💰 Est. Value: $${offer.total_amount}\n`;
  message += `🎯 Priority Score: ${offer.priority_score}\n`;
  message += `📲 Channel: ${offer.channel}\n\n`;
});

message += `━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
message += `⏱️ Please decide within 2 hours\n`;
message += `The highest-scored offer is recommended.`;

// Create Telegram inline keyboard
const keyboard = {
  inline_keyboard: [
    ...allOffers.map(offer => [{
      text: `${offer.is_recommended ? '⭐ ' : ''}Accept Offer ${offer.offer_number} - ${offer.guest_name}`,
      callback_data: `accept_offer_${offer.deal_id}`
    }]),
    [{ text: '❌ Decline All Offers', callback_data: `decline_all_${data.property_id}_${data.detected_check_in}` }],
    [{ text: 'ℹ️ Need More Time (Hold 24h)', callback_data: `hold_offers_${data.property_id}_${data.detected_check_in}` }]
  ]
};

// Create conflict record for control panel
const conflictRecord = {
  conflict_id: `CONFLICT-${Date.now()}`,
  property_id: data.property_id,
  property_name: data.property_name,
  check_in_date: data.detected_check_in,
  check_out_date: data.detected_check_out,
  offers: JSON.stringify(allOffers),
  status: 'pending_decision',
  created_at: new Date().toISOString(),
  owner_notified: true
};

return {
  // Notification data
  notification_message: message,
  keyboard: keyboard,
  owner_contact: data.owner_contact,
  preferred_platform: data.preferred_platform,

  // New deal data for current inquiry
  new_deal_id: newDealId,

  // All offers for reference
  all_offers: allOffers,
  conflict_record: conflictRecord,

  // Original context
  ...data
};

// Prepare response for the guest (competing offer situation)
const data = $json;

const responseText = `Thanks for your interest in ${data.property_name} for ${data.detected_check_in} to ${data.detected_check_out}! 🏠\n\nI want to be upfront with you - we have multiple guests interested in these same dates. I've notified the property owner to review all offers.\n\nYou'll hear back within 2 hours with a decision. Your offer is being considered! 🤞\n\nIn the meantime, is there anything else you'd like to know about the property?`;

return {
  response_text: responseText,
  conversation_id: data.conversation_id,
  contact_id: data.contact_id,
  property_id: data.property_id,
  stage: 'awaiting_owner_decision',
  history: data.history || [],
  collected: data.collected || {},
  channel: data.channel,
  recipient: data.contact_id
};

// Return result for competing offer flow
return {
  success: true,
  message_sent: true,
  flow: 'conflicting_offer',
  conflict_id: $('Format Owner Notification').item.json.conflict_record.conflict_id,
  response_text: $('Prepare Guest Response (Competing)').item.json.response_text
};

