// Process AI Agent response and prepare for saving
const context = $('Detect Competing Offers').item.json;
const aiResponse = $input.item.json;

// Extract the AI's response text
const responseText = aiResponse.output || aiResponse.text || 'I apologize, I encountered an issue. Please try again.';

// Update conversation history
const history = context.history || [];
history.push({ role: 'user', content: context.user_message, timestamp: new Date().toISOString() });
history.push({ role: 'assistant', content: responseText, timestamp: new Date().toISOString() });

// Keep only last 20 messages to prevent overflow
const trimmedHistory = history.slice(-20);

// Determine new stage based on conversation
let newStage = context.stage;
if (responseText.toLowerCase().includes('payment link')) {
  newStage = 'payment_pending';
} else if (responseText.toLowerCase().includes('check-in') || responseText.toLowerCase().includes('check out')) {
  newStage = 'collecting_dates';
} else if (responseText.toLowerCase().includes('confirm') && responseText.toLowerCase().includes('book')) {
  newStage = 'confirming_booking';
}

// Extract any collected data from AI response (simplified)
const collected = context.collected || {};

// Look for dates in AI intermediate steps if available
if (aiResponse.intermediateSteps) {
  for (const step of aiResponse.intermediateSteps) {
    if (step.action?.tool === 'check_availability') {
      collected.check_in = step.action.toolInput?.check_in_date;
      collected.check_out = step.action.toolInput?.check_out_date;
    }
    if (step.action?.tool === 'create_booking_hold') {
      collected.guest_name = step.action.toolInput?.guest_name;
      collected.guest_email = step.action.toolInput?.guest_email;
      newStage = 'booking_created';
    }
  }
}

return {
  // Response to send
  response_text: responseText,

  // Conversation state to save
  conversation_id: context.conversation_id,
  contact_id: context.contact_id,
  property_id: context.property_id,
  stage: newStage,
  history: trimmedHistory,
  collected: collected,

  // Messaging info
  channel: context.channel,
  recipient: context.contact_id
};

// Return result to calling workflow
return {
  success: true,
  message_sent: true,
  conversation_id: $('Process AI Response').item.json.conversation_id,
  response_text: $('Process AI Response').item.json.response_text
};

// Process owner decision callback
const data = $json;
const callbackData = data.body?.callback_data || data.callback_data || '';
const messageId = data.body?.message_id || data.message?.message_id;
const chatId = data.body?.chat?.id || data.message?.chat?.id;

let action = '';
let dealId = '';
let propertyId = '';
let checkIn = '';

if (callbackData.startsWith('accept_offer_')) {
  action = 'accept';
  dealId = callbackData.replace('accept_offer_', '');
} else if (callbackData.startsWith('decline_all_')) {
  action = 'decline_all';
  const parts = callbackData.replace('decline_all_', '').split('_');
  propertyId = parts[0];
  checkIn = parts.slice(1).join('_');
} else if (callbackData.startsWith('hold_offers_')) {
  action = 'hold';
  const parts = callbackData.replace('hold_offers_', '').split('_');
  propertyId = parts[0];
  checkIn = parts.slice(1).join('_');
}

return {
  action,
  deal_id: dealId,
  property_id: propertyId,
  check_in: checkIn,
  message_id: messageId,
  chat_id: chatId,
  raw_callback: callbackData
};

// Prepare notifications for accepted and declined guests
const data = $json;
const declinedOffers = data.declined_offers || [];

// Message for accepted guest
const acceptedMessage = `🎉 *Great news!*\n\nYour booking request for *${data.property_name}* has been ACCEPTED!\n\n📅 Check-in: ${data.check_in_date}\n📅 Check-out: ${data.check_out_date}\n💰 Total: $${data.total_amount}\n\nYou'll receive a payment link shortly to confirm your reservation. Welcome! 🏠`;

// Message for declined guests
const declinedMessage = `Hi there,\n\nThank you for your interest in *${data.property_name}* for ${data.check_in_date} to ${data.check_out_date}.\n\nUnfortunately, the property owner has accepted another booking for these dates. 😔\n\nWould you like me to:\n1. Check alternative dates for this property?\n2. Show you similar properties that are available?\n\nJust let me know! 🏡`;

return {
  accepted: {
    contact_id: data.accepted_contact,
    channel: data.accepted_channel,
    message: acceptedMessage,
    guest_name: data.accepted_guest
  },
  declined: declinedOffers ? declinedOffers.map(d => ({
    contact_id: d.contact_id,
    channel: d.channel,
    message: declinedMessage,
    guest_name: d.guest_name
  })) : [],
  property_name: data.property_name,
  accepted_deal_id: data.accepted_deal_id
};

// Split declined offers for individual notifications
const data = $input.first().json;
const declined = data.declined || [];

return declined.map(d => ({ json: d }));

// Prepare decline notifications for all guests
const guests = $input.all().map(i => i.json);

return guests.map(g => ({
  json: {
    contact_id: g.contact_id,
    channel: g.channel,
    message: `Hi ${g.guest_name},\n\nThank you for your interest in *${g.property_name}* for ${g.check_in_date} to ${g.check_out_date}.\n\nUnfortunately, the property owner has decided not to accept bookings for these dates at this time.\n\nWould you like me to check alternative dates or show you similar properties?\n\nLet me know how I can help! 🏡`
  }
}));

// Universal Message Sender - ONE node handles ALL channels
const input = $input.item.json;

const channel = (input.channel || input.preferred_platform || 'telegram').toLowerCase();
const recipient = input.recipient || input.chat_id || input.phone || input.sender_id;
const message = input.message || input.text || input.body || input.input;
const buttons = input.buttons || input.inline_keyboard || null;
const mediaUrl = input.media_url || null;
const customerId = input.customer_id || null;

// Validate required fields
if (!recipient || !message) {
  return {
    success: false,
    error: 'Missing recipient or message',
    channel: channel
  };
}

// Return standardized output for the appropriate channel
return {
  channel: channel,
  recipient: recipient,
  message: message,
  buttons: buttons,
  mediaUrl: mediaUrl,
  customer_id: customerId,
  timestamp: new Date().toISOString()
};

// Log Telegram send - FREE, no cost
const normalized = $('Normalize Input').item.json;
const result = $input.item.json;

return {
  success: true,
  channel: 'telegram',
  recipient: normalized.recipient,
  message_id: result.message_id || result.result?.message_id,
  customer_id: normalized.customer_id,
  cost_usd: 0.00,
  cost_type: 'free'
};

// Calculate WhatsApp cost and log
const normalized = $('Normalize Input').item.json;
const result = $input.item.json;

// WhatsApp pricing (template message): $0.005 per message
const costUsd = 0.005;

return {
  success: true,
  channel: 'whatsapp',
  recipient: normalized.recipient,
  message_id: result.messages?.[0]?.id || result.message_id,
  customer_id: normalized.customer_id,
  cost_usd: costUsd,
  cost_type: 'twilio_whatsapp'
};

// Calculate SMS cost and log
const normalized = $('Normalize Input').item.json;
const result = $input.item.json;

// Twilio SMS pricing: $0.0079 per outbound SMS (US)
// Use actual price from Twilio response if available
const costUsd = result.price ? Math.abs(parseFloat(result.price)) : 0.0079;

return {
  success: true,
  channel: 'sms',
  recipient: normalized.recipient,
  message_id: result.sid || result.message_sid,
  customer_id: normalized.customer_id,
  cost_usd: costUsd,
  cost_type: 'twilio_sms'
};

// Format successful response
const input = $input.item.json;
return {
  success: true,
  channel: input.channel || 'unknown',
  recipient: input.recipient || input.chat_id || input.to,
  messageId: input.message_id || input.id || null,
  cost_tracked: (input.cost_usd || 0) > 0,
  timestamp: new Date().toISOString()
};

// Universal Message Sender - ONE node handles ALL channels
const input = $input.item.json;

const channel = (input.channel || input.preferred_platform || 'telegram').toLowerCase();
const recipient = input.recipient || input.chat_id || input.phone || input.sender_id;
const message = input.message || input.text || input.body || input.input;
const buttons = input.buttons || input.inline_keyboard || null;
