  messageId: input.message_id || input.id || null,
  cost_tracked: (input.cost_usd || 0) > 0,
  timestamp: new Date().toISOString()
};

// Determine which automation to run based on trigger
const now = new Date();
const hour = now.getHours();
const dayOfWeek = now.getDay();
const dayOfMonth = now.getDate();

let automationType;
if (dayOfMonth === 1 && hour === 0) {
  automationType = 'monthly_reset';
} else if (dayOfWeek === 1 && hour === 10) {
  automationType = 'weekly_report';
} else if (hour >= 17) {
  automationType = 'evening_check';
} else {
  automationType = 'morning_check';
}

return {
  automation_type: automationType,
  trigger_time: now.toISOString(),
  date_today: now.toISOString().split('T')[0]
};

// Prepare monthly reset notification
const data = $input.item.json;
const lastMonthUsage = data.last_month_usage || 0;
const budget = data.monthly_budget || 30;
const usagePercent = ((lastMonthUsage / budget) * 100).toFixed(1);

const now = new Date();
const currentMonth = now.toLocaleString('default', { month: 'long', year: 'numeric' });
const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1)
  .toLocaleString('default', { month: 'long', year: 'numeric' });

